    {"id": 5012, "level": "beginner", "topic": "Naive Bayes", "difficulty": "medium", "type": "mcq", "title": "NB for text", "question": "Which NB variant is best for text counts?", "options": ["MultinomialNB", "GaussianNB", "BernoulliNB only", "None"], "answer": "MultinomialNB", "hint": "Word counts.", "explanation": "MultinomialNB handles word count features."},
