    {"id": 7416, "level": "intermediate", "topic": "File Upload", "difficulty": "medium", "type": "mcq", "title": "Web shell", "question": "An uploaded script giving command execution is a:", "options": ["Web shell", "Firewall", "Token", "Hash"], "answer": "Web shell", "hint": "Remote commands.", "explanation": "A web shell runs attacker commands on the server."},
    {"id": 7417, "level": "intermediate", "topic": "Command Injection", "difficulty": "medium", "type": "mcq", "title": "Chain commands", "question": "Which character chains OS commands?", "options": ["Semicolon ;", "Hash #", "At @", "Tilde ~"], "answer": "Semicolon ;", "hint": "Separator.", "explanation": "Attacker input like '; rm -rf /' chains commands."},
    {"id": 7418, "level": "intermediate", "topic": "Command Injection", "difficulty": "hard", "type": "mcq", "title": "The fix", "question": "The safe way to run commands is:", "options": ["Argument-list API, no shell", "String concatenation", "Eval", "Bare shell"], "answer": "Argument-list API, no shell", "hint": "No shell.", "explanation": "Passing args as a list avoids shell interpretation."},
    {"id": 7419, "level": "intermediate", "topic": "Hashcat", "difficulty": "easy", "type": "mcq", "title": "Slow hashes", "question": "Which password hash is intentionally slow?", "options": ["bcrypt", "MD5", "SHA-1", "CRC32"], "answer": "bcrypt", "hint": "GPU resistant.", "explanation": "bcrypt/Argon2 slow each guess, defeating brute force."},
    {"id": 7420, "level": "intermediate", "topic": "Linux PrivEsc", "difficulty": "medium", "type": "mcq", "title": "SUID", "question": "SUID binaries run with:", "options": ["The file owner's privileges", "No privileges", "User's privileges only", "Random"], "answer": "The file owner's privileges", "hint": "Root-owned.", "explanation": "A root-owned SUID binary can be exploited for root."},
    {"id": 7421, "level": "intermediate", "topic": "Linux PrivEsc", "difficulty": "hard", "type": "output", "title": "Check sudo", "question": "Which command lists your sudo rights? One word:", "answer": "sudo -l", "hint": "Dash l.", "explanation": "sudo -l shows what you may run with elevated rights."},
    {"id": 7422, "level": "intermediate", "topic": "Windows PrivEsc", "difficulty": "medium", "type": "mcq", "title": "Token attack", "question": "SeImpersonatePrivilege enables which attacks?", "options": ["Potato exploits", "SQL injection", "XSS", "CSRF"], "answer": "Potato exploits", "hint": "Token.", "explanation": "Potato-style attacks impersonate tokens to reach SYSTEM."},
    {"id": 7423, "level": "intermediate", "topic": "Lateral Movement", "difficulty": "medium", "type": "mcq", "title": "Pass the hash", "question": "Pass-the-Hash reuses:", "options": ["The password hash", "The password", "A cookie", "A token"], "answer": "The password hash", "hint": "Not plaintext.", "explanation": "Attackers authenticate with the hash, no password needed."},
    {"id": 7424, "level": "intermediate", "topic": "Persistence", "difficulty": "medium", "type": "mcq", "title": "Linux backdoor", "question": "Which is a common Linux persistence point?", "options": ["SSH authorized keys", "Browser cache", "Swap file", "Logs"], "answer": "SSH authorized keys", "hint": "Auto-login.", "explanation": "Adding an attacker key grants persistent SSH access."},
    {"id": 7425, "level": "intermediate", "topic": "Hardening", "difficulty": "easy", "type": "mcq", "title": "SSH best practice", "question": "Harden SSH by:", "options": ["Disabling root login and using keys", "Allowing root password", "Opening port 23", "No firewall"], "answer": "Disabling root login and using keys", "hint": "Keys over passwords.", "explanation": "Key auth + no root login closes the top SSH risk."},
    {"id": 7426, "level": "intermediate", "topic": "SIEM", "difficulty": "easy", "type": "mcq", "title": "Full form", "question": "SIEM stands for:", "options": ["Security Information and Event Management", "System Internet Error Monitor", "Secure Input Event Module", "None"], "answer": "Security Information and Event Management", "hint": "Logs + correlation.", "explanation": "SIEM correlates logs to detect attack patterns."},
    {"id": 7427, "level": "intermediate", "topic": "IDS/IPS", "difficulty": "easy", "type": "mcq", "title": "Alert vs block", "question": "An IPS differs from an IDS by:", "options": ["Blocking threats", "Only alerting", "Storing logs", "Encrypting"], "answer": "Blocking threats", "hint": "Prevention.", "explanation": "IDS alerts; IPS actively blocks."},
    {"id": 7428, "level": "intermediate", "topic": "Threat Intel", "difficulty": "medium", "type": "mcq", "title": "Evidence", "question": "An IOC is:", "options": ["Indicator of Compromise", "Internal Object Code", "Input Output Control", "None"], "answer": "Indicator of Compromise", "hint": "Evidence.", "explanation": "IOCs are evidence like malicious IPs, domains, hashes."},
    {"id": 7429, "level": "intermediate", "topic": "Forensics", "difficulty": "easy", "type": "mcq", "title": "Evidence rule", "question": "Never analyze the original — always:", "options": ["Image it first", "Wipe it", "Reboot it", "Delete logs"], "answer": "Image it first", "hint": "Copy.", "explanation": "Image and hash the copy to preserve the original."},
    {"id": 7430, "level": "intermediate", "topic": "Forensics", "difficulty": "hard", "type": "output", "title": "Order", "question": "Capture the most volatile evidence first: memory or disk? One word:", "answer": "Memory", "hint": "Lost on reboot.", "explanation": "Memory is lost first, so dump it before disk."},

    # ---------------- ADVANCED ----------------
    {"id": 7501, "level": "advanced", "topic": "Zero-Days", "difficulty": "medium", "type": "mcq", "title": "No patch", "question": "A zero-day is unknown to:", "options": ["The vendor", "Attackers", "Everyone forever", "No one"], "answer": "The vendor", "hint": "Zero warning.", "explanation": "Vendor has no patch — zero days of warning."},
    {"id": 7502, "level": "advanced", "topic": "Buffer Overflow", "difficulty": "hard", "type": "mcq", "title": "Overwrite target", "question": "A buffer overflow overwrites the ______ to hijack execution.", "options": ["Return address", "File name", "Password", "MAC"], "answer": "Return address", "hint": "Stack.", "explanation": "Overwriting the return address redirects execution."},
    {"id": 7503, "level": "advanced", "topic": "ROP", "difficulty": "hard", "type": "mcq", "title": "Bypass NX", "question": "ROP bypasses non-executable stack by:", "options": ["Reusing existing code gadgets", "Injecting new code", "Disabling NX", "No method"], "answer": "Reusing existing code gadgets", "hint": "Code reuse.", "explanation": "ROP chains existing gadgets — no injected code needed."},
    {"id": 7504, "level": "advanced", "topic": "Heap", "difficulty": "hard", "type": "mcq", "title": "Dangling pointer", "question": "Use-after-free exploits a pointer that:", "options": ["Still references freed memory", "Was never used", "Points to disk", "Is encrypted"], "answer": "Still references freed memory", "hint": "Freed but used.", "explanation": "A dangling pointer lets attackers reclaim the freed space."},
    {"id": 7505, "level": "advanced", "topic": "Kernel", "difficulty": "hard", "type": "mcq", "title": "Rootkit hides", "question": "A rootkit hides malicious modules from:", "options": ["The OS itself", "The BIOS", "The CPU only", "Nothing"], "answer": "The OS itself", "hint": "Lies to tools.", "explanation": "A compromised kernel can lie to every userland tool."},
    {"id": 7506, "level": "advanced", "topic": "SSRF", "difficulty": "medium", "type": "mcq", "title": "Cloud metadata", "question": "The prime SSRF target in the cloud is:", "options": ["169.254.169.254", "127.0.0.1", "192.168.1.1", "8.8.8.8"], "answer": "169.254.169.254", "hint": "Metadata.", "explanation": "Cloud metadata at 169.254.169.254 leaks credentials."},
    {"id": 7507, "level": "advanced", "topic": "Deserialization", "difficulty": "hard", "type": "mcq", "title": "Object rebuild", "question": "Unsafe deserialization executes code during:", "options": ["Object reconstruction", "Compilation", "Hashing", "Encoding"], "answer": "Object reconstruction", "hint": "Gadget chain.", "explanation": "Rebuilding objects can trigger attacker-controlled code."},
    {"id": 7508, "level": "advanced", "topic": "SSTI", "difficulty": "hard", "type": "mcq", "title": "Template RCE", "question": "SSTI can ultimately achieve:", "options": ["Remote code execution", "Data backup", "Logging", "Encryption"], "answer": "Remote code execution", "hint": "Server shell.", "explanation": "Template injection often leads to full RCE."},
    {"id": 7509, "level": "advanced", "topic": "Cloud", "difficulty": "easy", "type": "mcq", "title": "Responsibility", "question": "In the shared responsibility model, YOU secure:", "options": ["Your data and configuration", "The physical data center", "The hypervisor", "Nothing"], "answer": "Your data and configuration", "hint": "In the cloud.", "explanation": "Provider secures infra; you secure what you deploy."},
    {"id": 7510, "level": "advanced", "topic": "Cloud", "difficulty": "medium", "type": "mcq", "title": "Common breach", "question": "Most cloud breaches are:", "options": ["Misconfigurations", "Zero-days", "Physical theft", "Quantum"], "answer": "Misconfigurations", "hint": "Public buckets.", "explanation": "Public S3 buckets and weak IAM cause most cloud breaches."},
    {"id": 7511, "level": "advanced", "topic": "IAM", "difficulty": "medium", "type": "mcq", "title": "Wildcard risk", "question": "An IAM role with s3:* permissions is:", "options": ["Over-privileged", "Least privilege", "Secure", "Unused"], "answer": "Over-privileged", "hint": "Too broad.", "explanation": "Wildcards grant far more access than needed."},
    {"id": 7512, "level": "advanced", "topic": "Docker", "difficulty": "medium", "type": "mcq", "title": "Container escape", "question": "A container escape reaches the host because containers:", "options": ["Share the host kernel", "Are fully isolated", "Have no host", "Use separate kernels"], "answer": "Share the host kernel", "hint": "Same kernel.", "explanation": "Shared kernel means escape reaches host and all containers."},
    {"id": 7513, "level": "advanced", "topic": "Docker", "difficulty": "medium", "type": "mcq", "title": "Never mount", "question": "Never mount which socket into a container?", "options": ["Docker socket", "MySQL socket", "SSH socket", "HTTP socket"], "answer": "Docker socket", "hint": "/var/run/docker.sock.", "explanation": "Mounting the Docker socket grants host control."},
    {"id": 7514, "level": "advanced", "topic": "Kubernetes", "difficulty": "hard", "type": "mcq", "title": "Cluster takeover", "question": "A privileged pod can compromise the cluster via:", "options": ["The API server", "The browser", "Email", "No path"], "answer": "The API server", "hint": "Control plane.", "explanation": "Pod access to the API server can own the whole cluster."},
    {"id": 7515, "level": "advanced", "topic": "Serverless", "difficulty": "medium", "type": "mcq", "title": "Function risk", "question": "The biggest serverless risk is:", "options": ["Over-privileged roles", "Slow code", "Long logs", "No users"], "answer": "Over-privileged roles", "hint": "Permissions.", "explanation": "One over-privileged function can breach the cloud."},
    {"id": 7516, "level": "advanced", "topic": "Zero Trust", "difficulty": "easy", "type": "mcq", "title": "Mantra", "question": "The Zero Trust mantra is:", "options": ["Never trust, always verify", "Trust inside only", "Verify once", "Perimeter is enough"], "answer": "Never trust, always verify", "hint": "No implicit trust.", "explanation": "Every request is verified regardless of location."},
    {"id": 7517, "level": "advanced", "topic": "Active Directory", "difficulty": "hard", "type": "mcq", "title": "Crown jewel", "question": "The highest-privilege AD group is:", "options": ["Domain Admins", "Users", "Guests", "Auditors"], "answer": "Domain Admins", "hint": "Full domain.", "explanation": "Domain Admins control the entire domain."},
    {"id": 7518, "level": "advanced", "topic": "Active Directory", "difficulty": "medium", "type": "mcq", "title": "Attack path map", "question": "Which tool maps AD attack paths?", "options": ["BloodHound", "Wireshark", "Nmap", "Hashcat"], "answer": "BloodHound", "hint": "Graph.", "explanation": "BloodHound graphs the path from user to Domain Admin."},
    {"id": 7519, "level": "advanced", "topic": "Kerberos", "difficulty": "hard", "type": "mcq", "title": "Golden ticket", "question": "A Golden Ticket forges the TGT by compromising:", "options": ["KRBTGT hash", "User password", "A certificate", "A cookie"], "answer": "KRBTGT hash", "hint": "Domain skeleton key.", "explanation": "The KRBTGT hash forges unlimited domain access."},
    {"id": 7520, "level": "advanced", "topic": "APT", "difficulty": "medium", "type": "mcq", "title": "Living off land", "question": "APTs prefer living-off-the-land to:", "options": ["Avoid detection", "Be faster", "Save money", "Use no tools"], "answer": "Avoid detection", "hint": "Legit tools.", "explanation": "Built-in tools blend in, evading signature detection."},
    {"id": 7521, "level": "advanced", "topic": "APT", "difficulty": "medium", "type": "output", "title": "Dwell time", "question": "APTs often dwell for ______ before acting. One word:", "answer": "Months", "hint": "Patient.", "explanation": "APTs prioritize stealth and may lurk for months."},
    {"id": 7522, "level": "advanced", "topic": "Kill Chain", "difficulty": "medium", "type": "mcq", "title": "Stages count", "question": "The Cyber Kill Chain has how many stages?", "options": ["7", "5", "10", "3"], "answer": "7", "hint": "Recon to actions.", "explanation": "Seven stages from reconnaissance to actions on objectives."},
    {"id": 7523, "level": "advanced", "topic": "Ransomware", "difficulty": "easy", "type": "mcq", "title": "Only cure", "question": "The only reliable ransomware recovery is:", "options": ["Offline backups", "Paying ransom", "Rebooting", "Antivirus"], "answer": "Offline backups", "hint": "Restore.", "explanation": "Offline backups restore data without paying."},
    {"id": 7524, "level": "advanced", "topic": "Supply Chain", "difficulty": "medium", "type": "mcq", "title": "Famous breach", "question": "Which breach backdoored a build system at scale?", "options": ["SolarWinds", "Equifax", "Target", "Heartbleed"], "answer": "SolarWinds", "hint": "Build pipeline.", "explanation": "SolarWinds compromised the build to hit thousands."},
    {"id": 7525, "level": "advanced", "topic": "AI/ML Security", "difficulty": "medium", "type": "mcq", "title": "Fool the model", "question": "An adversarial example:", "options": ["Tricks a model with tiny perturbations", "Fixes the model", "Trains faster", "Encrypts data"], "answer": "Tricks a model with tiny perturbations", "hint": "Misclassify.", "explanation": "Imperceptible noise flips confident predictions."},
    {"id": 7526, "level": "advanced", "topic": "LLM Security", "difficulty": "medium", "type": "mcq", "title": "Override prompt", "question": "Prompt injection overrides the:", "options": ["System prompt", "Firewall", "Database", "CPU"], "answer": "System prompt", "hint": "Ignore instructions.", "explanation": "Crafted input overrides the model's system instructions."},
    {"id": 7527, "level": "advanced", "topic": "Blockchain", "difficulty": "hard", "type": "mcq", "title": "DAO hack", "question": "The DAO hack exploited:", "options": ["Reentrancy", "SQL injection", "XSS", "Phishing"], "answer": "Reentrancy", "hint": "Call before state update.", "explanation": "Reentrancy re-entered the function before state updated."},
    {"id": 7528, "level": "advanced", "topic": "IoT", "difficulty": "easy", "type": "mcq", "title": "Botnet", "question": "Mirai enslaved IoT devices via:", "options": ["Default credentials", "Zero-days", "Quantum", "Physical access"], "answer": "Default credentials", "hint": "admin/admin.", "explanation": "Mirai used default passwords to build a massive botnet."},
    {"id": 7529, "level": "advanced", "topic": "Quantum", "difficulty": "medium", "type": "mcq", "title": "Break RSA", "question": "Which algorithm breaks RSA on quantum computers?", "options": ["Shor's algorithm", "Grover's algorithm", "AES", "DES"], "answer": "Shor's algorithm", "hint": "Factorization.", "explanation": "Shor's factors large numbers, breaking RSA and ECC."},
    {"id": 7530, "level": "advanced", "topic": "Threat Hunting", "difficulty": "medium", "type": "mcq", "title": "Start point", "question": "A threat hunt starts with a:", "options": ["Hypothesis", "Patch", "Backup", "Reboot"], "answer": "Hypothesis", "hint": "An idea.", "explanation": "Hunts begin with a hypothesis about adversary behavior."},
