@app.route("/ielts")
def ielts_page():
    cur = mysql.connection.cursor()

    # 1) IELTS category id find karo
    cur.execute("SELECT id FROM categories WHERE level = 'IELTS' LIMIT 1")
    cat_row = cur.fetchone()

    if not cat_row:
        cur.close()
        books = []
    else:
        cat_id = cat_row[0]

        # 2) Approved IELTS books lo
        cur.execute(
            """
            SELECT id, title, author, image_url,
                   COALESCE(download_count, 0),
                   COALESCE(view_count, 0),
                   description, language
            FROM documents
            WHERE category_id = %s AND approved = 1
            ORDER BY id DESC
            """,
            (cat_id,),
        )
        rows = cur.fetchall()
        books = [
            {
                "id": r[0],
                "title": r[1],
                "author": r[2],
                "image_url": r[3],
                "download_count": r[4],
                "view_count": r[5],
                "description": r[6],
                "language": r[7],
            }
            for r in rows
        ]
        cur.close()

    return redirect("/learn/ielts")


