@app.route("/leaderboard")
def leaderboard():
    official_user_id = get_site_setting("official_user_id")

    cur = mysql.connection.cursor()
    if official_user_id:
        cur.execute(
            """
            SELECT u.id, u.username, u.first_name, u.last_name, u.avatar_url, SUM(up.points) AS total_points
            FROM user_points up
            JOIN users u ON up.user_id = u.id
            WHERE u.id != %s
            GROUP BY u.id
            ORDER BY total_points DESC
            LIMIT 50
        """,
            (official_user_id,),
        )
    else:
        cur.execute("""
            SELECT u.id, u.username, u.first_name, u.last_name, u.avatar_url, SUM(up.points) AS total_points
            FROM user_points up
            JOIN users u ON up.user_id = u.id
            GROUP BY u.id
            ORDER BY total_points DESC
            LIMIT 50
        """)
    rows = cur.fetchall()
    cur.close()

    leaderboard = []
    for row in rows:
        full_name = ((row[2] or "") + " " + (row[3] or "")).strip()
        if not full_name:
            full_name = row[1]
        leaderboard.append(
            {
                "user_id": row[0],
                "username": row[1],
                "name": full_name,
                "avatar_url": row[4],
                "points": row[5],
                "is_official": is_official_user(row[0]),
            }
        )

    current_user_rank = None
    current_user_points = 0
    if "user_id" in session:
        uid = session["user_id"]
        cur = mysql.connection.cursor()
        cur.execute("SELECT SUM(points) FROM user_points WHERE user_id = %s", (uid,))
        total = cur.fetchone()[0] or 0
        current_user_points = total

        if official_user_id and str(uid) != official_user_id:
            cur.execute(
                """
                SELECT COUNT(*) + 1 FROM (
                    SELECT user_id, SUM(points) AS total
                    FROM user_points
                    WHERE user_id != %s
                    GROUP BY user_id
                    HAVING SUM(points) > %s
                ) AS higher
            """,
                (official_user_id, total),
            )
        else:
            cur.execute(
                """
                SELECT COUNT(*) + 1 FROM (
                    SELECT user_id, SUM(points) AS total
                    FROM user_points
                    GROUP BY user_id
                    HAVING SUM(points) > %s
                ) AS higher
            """,
                (total,),
            )
        rank = cur.fetchone()[0]
        current_user_rank = rank
        cur.close()

    return render_template(
        "leaderboard.html",
        leaderboard=leaderboard,
        current_user_rank=current_user_rank,
        current_user_points=current_user_points,
    )


